// Тикет #4063a39b (4063a39b6d45e6f9e1d3d862) — עבר QA 13.10.2026, iPhone, TestFlight 1.0.0 (19), аккаунт клиента (מנהל תוכן).
// Факт 13.10 (скрин 4063a39b-ios-b19-admin-edit-rtl.png): админка «עריכת קטע» — поля «כותרת הקטע» (TextField) и «טקסט התפילה» (TextView):
// значение отображается справа; при очистке «כותרת הקטע» курсор справа; набранное «בדיקה» встаёт справа;
// дописанное в конец «טקסט התפילה» продолжает строку справа налево. Выход БЕЗ сохранения → «כל הקטעים מאושרים ואין טיוטות ממתינות.».
// Путь: профиль → «ממשק ניהול התוכן: מנהל תוכן…» → «בורא פרי העץ · נוסח אשכנז…» → «1, בורא פרי העץ…».
// Автоматически: значения полей (ввод, дописывание), выход без сохранения, отсутствие черновиков, значение после повторного входа не изменилось.
// @manual-check: положение текста и курсора внутри поля (XCUITest отдаёт только рамку поля) — сверить по скрину.
// Ничего не сохраняется (@prod-safe); страховка в finally — если черновик всё же появился, «מחיקת הטיוטה».
import { driver, expect } from '@wdio/globals';
import { scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { asAdmin, backToUser1, fieldAfter, hasDraft, discardDraft } from '../_lib/admin.ts';
import { openAdminHaetzSection, leaveEditWithoutSaving, NO_DRAFTS } from '../_lib/app-1310.ts';

const TITLE = 'כותרת הקטע', BODY = 'טקסט התפילה';

async function valueOf(label: string): Promise<string> {
  await scrollToText(label);
  const f = await fieldAfter(label);
  await f.waitForDisplayed();
  return (driver.isAndroid ? await f.getText() : (await f.getAttribute('value')) ?? '') ?? '';
}

describe('Админка в приложении: ввод справа налево', () => {
  afterEach(async () => { await toHome(); });

  it('AD-09 «עריכת קטע» «בורא פרי העץ»: «כותרת הקטע»/«טקסט התפילה» — значение, очистка, «בדיקה», дописывание; выход без сохранения → «כל הקטעים מאושרים…» #4063a39b @prod-safe @manual-check', async () => {
    await asAdmin();
    try {
      await openAdminHaetzSection();

      // 1. Значения полей есть (отображаются справа — @manual-check).
      const title0 = await valueOf(TITLE);
      const body0 = await valueOf(BODY);
      expect(title0.length).toBeGreaterThan(0);
      expect(body0.length).toBeGreaterThan(0);

      // 2. Очистить «כותרת הקטע» (курсор справа — @manual-check) → набрать «בדיקה» (встаёт справа — @manual-check).
      const t = await fieldAfter(TITLE);
      await t.click();
      await t.clearValue();
      const cleared = await valueOf(TITLE);
      expect(cleared === '' || cleared !== title0).toBe(true);   // iOS может вернуть placeholder вместо пустой строки
      await t.setValue('בדיקה');
      expect(await valueOf(TITLE)).toBe('בדיקה');

      // 3. Дописать в конец «טקסט התפילה» — продолжение строки (направление справа налево — @manual-check).
      const b = await fieldAfter(BODY);
      await b.click();
      await b.addValue(' בדיקה');
      const body1 = await valueOf(BODY);
      expect(body1.startsWith(body0.trimEnd().slice(0, 20))).toBe(true);
      expect(body1.trimEnd().endsWith('בדיקה')).toBe(true);

      // 4. Выход БЕЗ сохранения → на экране молитвы «כל הקטעים מאושרים ואין טיוטות ממתינות.».
      await leaveEditWithoutSaving();
      await expect(await scrollToText(NO_DRAFTS)).toBeDisplayed();

      // 5. Повторный вход: значения прежние.
      await openAdminHaetzSection();
      expect(await valueOf(TITLE)).toBe(title0);
      expect(await valueOf(BODY)).toBe(body0);
      expect(await hasDraft()).toBe(false);
      await leaveEditWithoutSaving();
    } finally {
      try {
        await openAdminHaetzSection();
        if (await hasDraft()) await discardDraft();
      } catch (e) {
        console.warn('[AD-09] страховка: проверить вручную, что у «בורא פרי העץ» нет черновика', e);
      } finally {
        await backToUser1();
      }
    }
  });
});
